messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB;
            font-family: sans-serif;
        }
        #info {
            position: absolute;
            top: 20px;
            left: 20px;
            color: white;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            pointer-events: none;
        }
        canvas {
            display: block;
        }
    </style>
</head>
<body>
    <div id="info">Red vs Blue Race</div>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 100;
        const START_Z = -20;
        const FINISH_Z = 60;
        const LANE_WIDTH = 6;
        const RACE_DURATION = 8000; // ms for one full loop

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 50, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
        camera.position.set(0, 15, -30);
        camera.lookAt(0, 0, 20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(20, 50, 20);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 150;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // --- Environment ---

        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 300);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a4a4a });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = 20;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track (Asphalt)
        const trackGeo = new THREE.PlaneGeometry(20, 120);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.set(0, 0.01, 20);
        track.receiveShadow = true;
        scene.add(track);

        // Lane Markings
        const lineGeo = new THREE.PlaneGeometry(0.5, 120);
        const lineMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const centerLine = new THREE.Mesh(lineGeo, lineMat);
        centerLine.rotation.x = -Math.PI / 2;
        centerLine.position.set(0, 0.02, 20);
        scene.add(centerLine);

        // Finish Line
        const finishLineGroup = new THREE.Group();
        const checkSize = 2;
        const checkColor1 = 0xffffff;
        const checkColor2 = 0x000000;

        for (let x = -4; x <= 4; x++) {
            for (let z = -1; z <= 1; z++) {
                const checkGeo = new THREE.PlaneGeometry(checkSize, checkSize);
                const color = (x + z) % 2 === 0 ? checkColor1 : checkColor2;
                const checkMat = new THREE.MeshStandardMaterial({ color: color });
                const check = new THREE.Mesh(checkGeo, checkMat);
                check.rotation.x = -Math.PI / 2;
                check.position.set(x * checkSize, 0.03, z * checkSize);
                finishLineGroup.add(check);
            }
            // Add pillars
            const pillarGeo = new THREE.CylinderGeometry(0.5, 0.5, 10);
            const pillarMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
            const pillar = new THREE.Mesh(pillarGeo, pillarMat);
            pillar.position.set(x * checkSize * 2.5, 5, 0);
            pillar.castShadow = true;
            finishLineGroup.add(pillar);
        }

        finishLineGroup.position.z = FINISH_Z;
        finishLineGroup.position.y = 0.02;
        scene.add(finishLineGroup);

        // Finish Banner
        const bannerGeo = new THREE.PlaneGeometry(10, 2);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0xffd700, side: THREE.DoubleSide });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 8, FINISH_Z);
        scene.add(banner);

        const textGeo = new THREE.PlaneGeometry(8, 1);
        const textMat = new THREE.MeshStandardMaterial({ color: 0x000000, side: THREE.DoubleSide });
        const textMesh = new THREE.Mesh(textGeo, textMat);
        textMesh.position.set(0, 8, FINISH_Z + 0.1);
        scene.add(textMesh);

        // --- Car Factory ---
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 0.8, 4.5);
            const chassisMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.8;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.6, 2.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: colorHex });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1.5, -0.5);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Windshield
            const windGeo = new THREE.PlaneGeometry(1.6, 0.5);
            const windMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const wind = new THREE.Mesh(windGeo, windMat);
            wind.position.set(0, 1.5, 0.75);
            wind.rotation.x = -0.2;
            carGroup.add(wind);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1, y: 0.4, z: 1.5 },
                { x: 1, y: 0.4, z: 1.5 },
                { x: -1, y: 0.4, z: -1.5 },
                { x: 1, y: 0.4, z: -1.5 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Headlights
            const lightGeo = new THREE.SphereGeometry(0.2);
            const lightMat = new THREE.MeshStandardMaterial({ color: 0xffff00, emissive: 0xffff00, emissiveIntensity: 0.5 });
            const leftLight = new THREE.Mesh(lightGeo, lightMat);
            leftLight.position.set(-0.6, 0.8, 2.3);
            carGroup.add(leftLight);
            const rightLight = new THREE.Mesh(lightGeo, lightMat);
            rightLight.position.set(0.6, 0.8, 2.3);
            carGroup.add(rightLight);

            // Tail lights
            const tailLightMat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.5 });
            const leftTail = new THREE.Mesh(lightGeo, tailLightMat);
            leftTail.position.set(-0.6, 0.8, -2.3);
            carGroup.add(leftTail);
            const rightTail = new THREE.Mesh(lightGeo, tailLightMat);
            rightTail.position.set(0.6, 0.8, -2.3);
            carGroup.add(rightTail);

            return carGroup;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);
        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let startTime = performance.now();

        function getCarPosition(time, isRed) {
            // Normalize time to 0-1 range
            const t = (time % RACE_DURATION) / RACE_DURATION;

            // Define keyframes for position (z-axis)
            // 0%: Start (-20)
            // 30%: Blue leads, Red behind
            // 60%: Overtake point
            // 90%: Red wins
            // 100%: Loop

            let zPos;

            if (isRed) {
                // Red starts slower, accelerates hard in middle, wins at end
                // Using a custom easing or simple interpolation
                if (t < 0.3) {
                    // Slow start
                    zPos = START_Z + (FINISH_Z - START_Z) * (t / 0.3) * 0.4; // Covers 40% of distance in 30% time
                } else if (t < 0.7) {
                    // Acceleration phase
                    const localT = (t - 0.3) / 0.4;
                    // Ease in-out
                    const eased = localT * localT * (3 - 2 * localT);
                    zPos = (START_Z + (FINISH_Z - START_Z) * 0.4) + (FINISH_Z - START_Z) * 0.6 * eased;
                } else {
                    // Final stretch
                    const localT = (t - 0.7) / 0.3;
                    zPos = FINISH_Z - (FINISH_Z - START_Z) * 0.05 * (1 - localT); // Small buffer
                }
            } else {
                // Blue starts fast, maintains speed, gets overtaken
                if (t < 0.5) {
                    // Fast start
                    zPos = START_Z + (FINISH_Z - START_Z) * (t / 0.5) * 0.6; // Covers 60% of distance in 50% time
                } else {
                    // Slows down slightly relative to red
                    const localT = (t - 0.5) / 0.5;
                    zPos = (START_Z + (FINISH_Z - START_Z) * 0.6) + (FINISH_Z - START_Z) * 0.35 * localT;
                }
            }

            return Math.max(START_Z, Math.min(FINISH_Z, zPos));
        }

        function animate() {
            requestAnimationFrame(animate);

            const currentTime = performance.now();
            const elapsed = currentTime - startTime;

            // Calculate positions
            const redZ = getCarPosition(elapsed, true);
            const blueZ = getCarPosition(elapsed, false);

            // Update car positions
            redCar.position.set(2, 0, redZ); // Red in right lane
            blueCar.position.set(-2, 0, blueZ); // Blue in left lane

            // Rotate wheels based on speed (approximate)
            const wheelRotation = elapsed * 0.005;
            redCar.children.forEach(child => {
                if (child.geometry && child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x = wheelRotation;
                }
            });
            blueCar.children.forEach(child => {
                if (child.geometry && child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x = wheelRotation;
                }
            });

            // Camera follow logic
            // Find the leading car
            const leadZ = Math.max(redZ, blueZ);
            const trailZ = Math.min(redZ, blueZ);
            const midZ = (leadZ + trailZ) / 2;

            // Smooth camera movement
            const targetCamZ = midZ - 10;
            camera.position.z += (targetCamZ - camera.position.z) * 0.05;
            camera.position.x = 0;
            camera.position.y = 15;
            camera.lookAt(0, 0, midZ + 10);

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
